async function generate(defaultPayload, sessionData) {
  console.log(`session data for search call ${JSON.stringify(sessionData)}`)
    // defaultPayload.context.bpp_uri = sessionData.subscriber_url
    const stops = defaultPayload.message.intent.fulfillment.stops;
    stops[0].location.descriptor.code = "start_station"
