        defaultPayload.message.intent.payment.collected_by = collector
      }
    }

    return defaultPayload;
}

/**
 * Validates incoming search request payload for ONDC TRV11 flow.
 * 
 * @param {Object} targetPayload - Incoming search payload
 * @param {Object} sessionData - Previous session data
 * 
 * @returns {Object}
 */
function validate(targetPayload, sessionData) {

  try {

    // =====================================================
    // Context Validation
    // =====================================================

    const context = targetPayload?.context;

    if (!context) {
      return {
        valid: false,
        code: 400,
        description: "context is required"
      };
    }

    const requiredContextFields = [
      "domain",
      "action",
      "timestamp",
      "transaction_id",
      "message_id",
      "bap_id",
      "bap_uri",
      "ttl",
      "version"
    ];

    for (const field of requiredContextFields) {

      if (
        context[field] === undefined ||
        context[field] === null ||
        context[field] === ""
      ) {
        return {
          valid: false,
          code: 400,
          description: `Missing context field: ${field}`
        };
      }
    }

    // Validate action
    if (context.action !== "search") {
      return {
        valid: false,
        code: 400,
        description: "Invalid action"
      };
    }

    // Validate domain
    if (context.domain !== "ONDC:TRV11") {
      return {
        valid: false,
        code: 400,
        description: "Invalid domain"
      };
    }

    // Validate version
    if (context.version !== "2.0.0") {
      return {
        valid: false,
        code: 400,
        description: "Unsupported version"
      };
    }

    // Validate timestamp
    if (isNaN(Date.parse(context.timestamp))) {
      return {
        valid: false,
        code: 400,
        description: "Invalid timestamp"
      };
    }

    // Validate TTL
    const ttlRegex = /^PT\d+S$/;

    if (!ttlRegex.test(context.ttl)) {
      return {
        valid: false,
        code: 400,
        description: "Invalid ttl format"
      };
    }

    // =====================================================
    // Location Validation
    // =====================================================

    if (!context.location?.country?.code) {
      return {
        valid: false,
        code: 400,
        description: "country.code is required"
      };
    }

    if (!context.location?.city?.code) {
      return {
        valid: false,
        code: 400,
        description: "city.code is required"
      };
    }

    // =====================================================
    // Message Validation
    // =====================================================

    const intent = targetPayload?.message?.intent;

    if (!intent) {
      return {
        valid: false,
        code: 400,
        description: "message.intent is required"
      };
    }

    // =====================================================
    // Fulfillment Validation
    // =====================================================

    const fulfillment = intent.fulfillment;

    if (!fulfillment) {
      return {
        valid: false,
        code: 400,
        description: "intent.fulfillment is required"
      };
    }

    // Vehicle validation
    if (!fulfillment.vehicle?.category) {
      return {
        valid: false,
        code: 400,
        description: "vehicle.category is required"
      };
    }

    // Stops validation
    if (
      !Array.isArray(fulfillment.stops) ||
      fulfillment.stops.length < 2
    ) {
      return {
        valid: false,
        code: 400,
        description: "At least START and END stops are required"
      };
    }

    let hasStart = false;
    let hasEnd = false;

    for (const stop of fulfillment.stops) {

      if (!stop.type) {
        return {
          valid: false,
          code: 400,
          description: "stop.type is required"
        };
      }

      if (!stop.location?.descriptor?.code) {
        return {
          valid: false,
          code: 400,
          description: `location.descriptor.code missing for ${stop.type}`
        };
      }

      if (stop.type === "START") {
        hasStart = true;
      }

      if (stop.type === "END") {
        hasEnd = true;
      }
    }

    if (!hasStart || !hasEnd) {
      return {
        valid: false,
        code: 400,
        description: "Both START and END stops are required"
      };
    }

    // =====================================================
    // Payment Validation
    // =====================================================

    const payment = intent.payment;

    if (!payment) {
      return {
        valid: false,
        code: 400,
        description: "intent.payment is required"
      };
    }

    if (!payment.collected_by) {
      return {
        valid: false,
        code: 400,
        description: "payment.collected_by is required"
      };
    }

    // Validate tags if present
    if (payment.tags) {

      if (!Array.isArray(payment.tags)) {
        return {
          valid: false,
          code: 400,
          description: "payment.tags must be an array"
        };
      }

      for (const tag of payment.tags) {

        if (!tag.descriptor?.code) {
          return {
            valid: false,
            code: 400,
            description: "tag.descriptor.code is required"
          };
        }

        if (tag.list && !Array.isArray(tag.list)) {
          return {
            valid: false,
            code: 400,
            description: "tag.list must be an array"
          };
        }
      }
    }

    // =====================================================
    // Session Validation
    // =====================================================

    // =====================================================
    // Success
    // =====================================================

    return {
      valid: true,
      code: 200,
      description: "Valid search request"
    };

  } catch (error) {

    return {
      valid: false,
      code: 500,
      description: error.message || "Internal validation error"
    };
  }
}

/**
 * Checks if the requirements for proceeding with the API call are met.
 * 
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * 
 * @returns {Object} { valid: boolean, code: number, description: string }
 */
function meetsRequirements(sessionData) {
  const userInputs =
    typeof sessionData?.user_inputs?.data === "string"
      ? JSON.parse(sessionData.user_inputs.data)
      : sessionData?.user_inputs || {};

  if (!userInputs.vehicle_category) {
    return {
      valid: false,
      code: 400,
      description: "Missing vehicle_category in user_inputs",
    };
  }

  if (!userInputs.city_code) {
    return {
      valid: false,
