/**
 * Validates the incoming request payload for an API call in the transaction flow.
 * 
 * @param {Object} targetPayload - The incoming request payload to validate.
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * 
 * @returns {Object} { valid: boolean, code: number, description: string }
 */
/**
 * Validates incoming search request payload for ONDC TRV11.
 * 
 * @param {Object} targetPayload - Incoming request payload
 * @param {Object} sessionData - Previous session data
 * 
 * @returns {Object}
 */
function validate(targetPayload, sessionData) {

  try {

    // =====================================================
    // Context Validation
    // =====================================================

    const context = targetPayload?.context;

    if (!context) {
      return {
        valid: false,
        code: 400,
        description: "context is required"
      };
    }

    const requiredContextFields = [
      "domain",
      "action",
      "timestamp",
      "transaction_id",
      "message_id",
      "bap_id",
      "bap_uri",
      "ttl",
      "version"
    ];

    for (const field of requiredContextFields) {

      if (
        context[field] === undefined ||
        context[field] === null ||
        context[field] === ""
      ) {
        return {
          valid: false,
          code: 400,
          description: `Missing context field: ${field}`
        };
      }
    }

    // Validate action
    if (context.action !== "search") {
      return {
        valid: false,
        code: 400,
        description: "Invalid action"
      };
    }

    // Validate domain
    if (context.domain !== "ONDC:TRV11") {
      return {
        valid: false,
        code: 400,
        description: "Invalid domain"
      };
    }

    // Validate version
    if (context.version !== "2.0.0") {
      return {
        valid: false,
        code: 400,
        description: "Unsupported version"
      };
    }

    // Validate timestamp
    if (isNaN(Date.parse(context.timestamp))) {
      return {
        valid: false,
        code: 400,
        description: "Invalid timestamp"
      };
    }

    // Validate TTL
    const ttlRegex = /^PT\d+S$/;

    if (!ttlRegex.test(context.ttl)) {
      return {
        valid: false,
        code: 400,
        description: "Invalid ttl format"
      };
    }

    // =====================================================
    // Location Validation
    // =====================================================

    if (!context.location?.country?.code) {
      return {
        valid: false,
        code: 400,
        description: "country.code is required"
      };
    }

    if (!context.location?.city?.code) {
      return {
        valid: false,
        code: 400,
        description: "city.code is required"
      };
    }

    // =====================================================
    // Intent Validation
    // =====================================================

    const intent = targetPayload?.message?.intent;

    if (!intent) {
      return {
        valid: false,
        code: 400,
        description: "message.intent is required"
      };
    }

    // =====================================================
    // Fulfillment Validation
    // =====================================================

    const fulfillment = intent.fulfillment;

    if (!fulfillment) {
      return {
        valid: false,
        code: 400,
        description: "intent.fulfillment is required"
      };
    }

    // Vehicle validation
    if (!fulfillment.vehicle?.category) {
      return {
        valid: false,
        code: 400,
        description: "vehicle.category is required"
      };
    }

    // =====================================================
    // Payment Validation
    // =====================================================

    const payment = intent.payment;

    if (!payment) {
      return {
        valid: false,
        code: 400,
        description: "intent.payment is required"
      };
    }

    if (!payment.collected_by) {
      return {
        valid: false,
        code: 400,
        description: "payment.collected_by is required"
      };
    }

    // =====================================================
    // Payment Tags Validation
    // =====================================================

    if (payment.tags) {

      if (!Array.isArray(payment.tags)) {
        return {
          valid: false,
          code: 400,
          description: "payment.tags must be an array"
        };
      }

      for (const tag of payment.tags) {

        if (!tag.descriptor?.code) {
          return {
            valid: false,
            code: 400,
            description: "tag.descriptor.code is required"
          };
        }

        if (tag.list && !Array.isArray(tag.list)) {
          return {
            valid: false,
            code: 400,
            description: "tag.list must be an array"
          };
        }

        if (Array.isArray(tag.list)) {

          for (const item of tag.list) {

            if (!item.descriptor?.code) {
              return {
                valid: false,
                code: 400,
                description: "tag.list.descriptor.code is required"
              };
            }

            if (
              item.value === undefined ||
              item.value === null ||
              item.value === ""
            ) {
              return {
                valid: false,
                code: 400,
                description: `Value missing for ${item.descriptor.code}`
              };
            }
          }
        }
      }
    }

    // =====================================================
    // Session Validation
    // =====================================================

    if (
      sessionData?.transaction_id &&
      sessionData.transaction_id !== context.transaction_id
    ) {
      return {
        valid: false,
        code: 400,
        description: "transaction_id mismatch"
      };
    }

    // =====================================================
    // Success
    // =====================================================

    return {
      valid: true,
      code: 200,
      description: "Valid search request"
    };

  } catch (error) {

    return {
      valid: false,
      code: 500,
      description: error.message || "Internal validation error"
    };
  }
}

/**
 * Checks if the requirements for proceeding with the API call are met.
 * 
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * 
 * @returns {Object} { valid: boolean, code: number, description: string }
 */
function meetsRequirements(sessionData) {
  const userInputs =
  typeof sessionData?.user_inputs?.data === "string"
    ? JSON.parse(sessionData.user_inputs.data)
    : sessionData?.user_inputs || sessionData;

  if (
     !userInputs.vehicle_category?.length &&
  !sessionData.vehicle_type?.length
  ) {
    return {
      valid: false,
      code: 400,
      description: `Missing vehicle_category|vehicle_type in user_inputs/sessionData`,
    };
  }

  if (!userInputs.city_code) {
    return {
      valid: false,
      code: 400,
      description: `Missing city_code in user_inputs`,
    };
  }

  if (!userInputs.start_code) {
    return {
      valid: false,
      code: 400,
      description: "Missing start_code in user_inputs",
    };
  }

  if (!userInputs.end_code) {
    return {
      valid: false,
      code: 400,
      description: "Missing end_code in user_inputs",
    };
  }

  if (!userInputs.bpp_id) {
    return {
      valid: false,
      code: 400,
      description: "Missing bpp_id in user_inputs",
    };
  }

  return {
    valid: true,
    code: 200,
    description: "Requirements met",
  };
}

