 * @returns {string} a zero-padded 6-digit numeric string
 */
function generate6DigitId() {
	return Math.floor(100000 + Math.random() * 900000).toString();
}

/**
 * Get the current ISO-8601 UTC timestamp.
 *
 * @returns {string} e.g. "2026-04-23T12:34:56.789Z"
 */
function currentTimestamp() {
	return new Date().toISOString();
}

/**
 * Convert an ISO 8601 duration string (e.g. "PT1H30M", "P2DT3H") to total seconds.
 *
 * Approximations used: 1 week = 7 days, 1 month ≈ 30.42 days (2628288 sec),
 * 1 year = 365 days. Not calendar-exact.
 *
 * @param {string} duration  ISO 8601 duration string
 * @returns {number} total seconds; 0 when the input is unparseable
 */
function isoDurToSec(duration) {
	const durRE =
		/P((\d+)Y)?((\d+)M)?((\d+)W)?((\d+)D)?T?((\d+)H)?((\d+)M)?((\d+)S)?/;
	const s = durRE.exec(duration);
	if (!s) return 0;

	return (
		(Number(s?.[2]) || 0) * 31536000 +
		(Number(s?.[4]) || 0) * 2628288 +
		(Number(s?.[6]) || 0) * 604800 +
		(Number(s?.[8]) || 0) * 86400 +
		(Number(s?.[10]) || 0) * 3600 +
		(Number(s?.[12]) || 0) * 60 +
		(Number(s?.[14]) || 0)
	);
}

/**
 * Mutate `payload.context` in place to set the city code from `inputs.city_code`.
 *
 * Version-aware: ONDC v1.x uses flat `context.city`, v2.x uses nested
 * `context.location.city.code`. Falls back to "*" when `city_code` is missing.
 * No-op when `inputs` is falsy.
 *
 * @param {Object} payload  payload with a `context` to mutate
 * @param {Object|null|undefined} inputs  object with optional `city_code`
 * @returns {string|undefined} "*" when inputs is falsy; otherwise undefined
 */
function setCityFromInputs(payload, inputs) {
	if (!inputs) return "*";
	const version =
		payload.context.version || payload.context.core_version || "2.0.0";
	if (version.startsWith("1")) {
		payload.context.city = inputs.city_code ?? "*";
	} else {
		payload.context.location.city.code = inputs.city_code ?? "*";
	}
}

/**
 * Build a form submission URL from session data.
 *
 * @param {string} domain       ONDC domain (e.g. "ONDC:RET10")
 * @param {string} formId       form identifier
 * @param {Object} sessionData  reads `mockBaseUrl`, `transactionId[0]`, `sessionId`
 * @returns {string} `${baseURL}/forms/${domain}/${formId}/?transaction_id=...&session_id=...`
 */
function createFormURL(domain, formId, sessionData) {
	const baseURL = sessionData.mockBaseUrl;
	const transactionId = sessionData.transactionId[0];
	const sessionId = sessionData.sessionId;
	return `${baseURL}/forms/${domain}/${formId}/?transaction_id=${transactionId}&session_id=${sessionId}`;
}

/**
 * Generate a consent handler from the Finvu AA Service.
 *
 * Reads the service base URL from `sessionData.finvuUrl` — the installing
 * service MUST include that origin in
 *   MockRunner.initSharedRunner({ allowedFetchBaseUrls: [...] })
 * otherwise the sandboxed fetch will be blocked.
 *
 * Times out after 10s via AbortController.
 *
 * @param {Object} sessionData  session data; `sessionData.finvuUrl` is required
 * @param {Object} params
 * @param {string} params.custId                customer ID (required)
 * @param {string} [params.templateName]        defaults to "FINVUDEMO_TESTING"
 * @param {string} [params.consentDescription]  defaults to "Gold Loan Account Aggregator Consent"
 * @param {string} [params.redirectUrl]         defaults to "https://google.co.in"
 * @returns {Promise<string>} the `consentHandler` returned by the AA service
 * @throws {Error} when `custId` or `sessionData.finvuUrl` is missing, on non-OK
 *   response, on missing `consentHandler` in the body, or on 10s timeout
 */
async function generateConsentHandler(
	sessionData,
	{
		custId,
		templateName = "FINVUDEMO_TESTING",
		consentDescription = "Gold Loan Account Aggregator Consent",
		redirectUrl = "https://google.co.in",
	},
) {
	if (!custId) {
		throw new Error("custId is required");
	}
	const baseUrl = sessionData && sessionData.finvuUrl;
	if (!baseUrl) {
		throw new Error("sessionData.finvuUrl is required");
	}

	const url = `${baseUrl}/finvu-aa/consent/generate`;

	const payload = {
		custId,
		templateName,
		consentDescription,
		redirectUrl,
	};

	console.log("Calling Finvu AA Service:", url);
	console.log("Consent request payload:", payload);

	const controller = new AbortController();
	const timeout = setTimeout(() => controller.abort(), 10000);

	try {
		const res = await fetch(url, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
			},
			body: JSON.stringify(payload),
			signal: controller.signal,
		});

		if (!res.ok) {
			const text = await res.text();
			throw new Error(`Request failed: ${res.status} ${text}`);
		}

		const data = await res.json();

		if (!data || !data.consentHandler) {
			throw new Error("Invalid response: consentHandler missing");
		}

		return data.consentHandler;
	} catch (err) {
		if (err && err.name === "AbortError") {
			throw new Error("Request timed out after 10 seconds");
		}
		throw err;
	} finally {
		clearTimeout(timeout);
	}
}

/**
 * Generates the mock payload for an API call in the transaction flow.
 * This function allows customization of the default payload using session data
 * from previous steps and user inputs.
 * 
 * @param {Object} defaultPayload - The base payload object with context already populated.
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * @param {Object} sessionData.user_inputs - User-provided input values for this step.
 * @param {*} sessionData.[key] - Any saved data from previous steps (defined in saveData config).
 * 
 * @returns {Object} The generated payload object to be sent in the API request.
 */


async function generate(defaultPayload, sessionData) {
  console.log(`session data for search call ${JSON.stringify(sessionData)}`)
    // defaultPayload.context.bpp_uri = sessionData.subscriber_url
    const stops = defaultPayload.message.intent.fulfillment.stops;
    stops[0].location.descriptor.code = "start_station"
    stops[1].location.descriptor.code = "end_station"
    if(sessionData.user_inputs){
      const {start_code, end_code, city_code, collector} = sessionData.user_inputs
      if(start_code){
        stops[0].location.descriptor.code = start_code
      }
      if(end_code){
        stops[1].location.descriptor.code = end_code
      }
      if(city_code){
        defaultPayload.context.location.city.code = city_code
      }
      if(collector){
        defaultPayload.message.intent.payment.collected_by = collector
      }
    }

    return defaultPayload;
}

/**
 * Validates incoming search request payload for ONDC TRV11 flow.
 * 
 * @param {Object} targetPayload - Incoming search payload
 * @param {Object} sessionData - Previous session data
 * 
 * @returns {Object}
 */
function validate(targetPayload, sessionData) {

  try {

    // =====================================================
    // Context Validation
    // =====================================================

    const context = targetPayload?.context;

    if (!context) {
      return {
        valid: false,
        code: 400,
        description: "context is required"
      };
    }

    const requiredContextFields = [
      "domain",
      "action",
      "timestamp",
      "transaction_id",
      "message_id",
      "bap_id",
      "bap_uri",
      "ttl",
      "version"
    ];

    for (const field of requiredContextFields) {

      if (
        context[field] === undefined ||
        context[field] === null ||
        context[field] === ""
      ) {
        return {
          valid: false,
          code: 400,
          description: `Missing context field: ${field}`
        };
      }
    }

    // Validate action
    if (context.action !== "search") {
      return {
        valid: false,
        code: 400,
        description: "Invalid action"
      };
    }

    // Validate domain
    if (context.domain !== "ONDC:TRV11") {
      return {
        valid: false,
        code: 400,
        description: "Invalid domain"
      };
    }

    // Validate version
    if (context.version !== "2.0.0") {
      return {
        valid: false,
        code: 400,
        description: "Unsupported version"
      };
    }

    // Validate timestamp
    if (isNaN(Date.parse(context.timestamp))) {
      return {
        valid: false,
        code: 400,
        description: "Invalid timestamp"
      };
    }

    // Validate TTL
    const ttlRegex = /^PT\d+S$/;

    if (!ttlRegex.test(context.ttl)) {
      return {
        valid: false,
        code: 400,
        description: "Invalid ttl format"
      };
    }

    // =====================================================
    // Location Validation
    // =====================================================

    if (!context.location?.country?.code) {
      return {
        valid: false,
        code: 400,
        description: "country.code is required"
      };
    }

    if (!context.location?.city?.code) {
      return {
        valid: false,
        code: 400,
        description: "city.code is required"
      };
    }

    // =====================================================
    // Message Validation
    // =====================================================

    const intent = targetPayload?.message?.intent;

    if (!intent) {
      return {
        valid: false,
        code: 400,
        description: "message.intent is required"
      };
    }

    // =====================================================
    // Fulfillment Validation
    // =====================================================

    const fulfillment = intent.fulfillment;

    if (!fulfillment) {
      return {
        valid: false,
        code: 400,
        description: "intent.fulfillment is required"
      };
    }

    // Vehicle validation
    if (!fulfillment.vehicle?.category) {
      return {
        valid: false,
        code: 400,
        description: "vehicle.category is required"
      };
    }

    // Stops validation
    if (
      !Array.isArray(fulfillment.stops) ||
      fulfillment.stops.length < 2
    ) {
      return {
        valid: false,
        code: 400,
        description: "At least START and END stops are required"
      };
    }

    let hasStart = false;
    let hasEnd = false;

    for (const stop of fulfillment.stops) {

      if (!stop.type) {
        return {
          valid: false,
          code: 400,
          description: "stop.type is required"
        };
      }

      if (!stop.location?.descriptor?.code) {
        return {
          valid: false,
          code: 400,
          description: `location.descriptor.code missing for ${stop.type}`
        };
      }

      if (stop.type === "START") {
        hasStart = true;
      }

      if (stop.type === "END") {
        hasEnd = true;
      }
    }

    if (!hasStart || !hasEnd) {
      return {
        valid: false,
        code: 400,
        description: "Both START and END stops are required"
      };
    }

    // =====================================================
    // Payment Validation
    // =====================================================

    const payment = intent.payment;

    if (!payment) {
      return {
        valid: false,
        code: 400,
        description: "intent.payment is required"
      };
    }

    if (!payment.collected_by) {
      return {
        valid: false,
        code: 400,
        description: "payment.collected_by is required"
      };
    }

    // Validate tags if present
    if (payment.tags) {

      if (!Array.isArray(payment.tags)) {
        return {
          valid: false,
          code: 400,
          description: "payment.tags must be an array"
        };
      }

      for (const tag of payment.tags) {

        if (!tag.descriptor?.code) {
          return {
            valid: false,
            code: 400,
            description: "tag.descriptor.code is required"
          };
        }

        if (tag.list && !Array.isArray(tag.list)) {
          return {
            valid: false,
            code: 400,
            description: "tag.list must be an array"
          };
        }
      }
    }

    // =====================================================
    // Session Validation
    // =====================================================

    // =====================================================
    // Success
    // =====================================================

    return {
      valid: true,
      code: 200,
      description: "Valid search request"
    };

  } catch (error) {

    return {
      valid: false,
      code: 500,
      description: error.message || "Internal validation error"
    };
  }
}
